#!/bin/zsh
# Saison 2 : scènes refaites avec les vues en pied du héros (hero_s2/sel_*.png), orientées vers l'interlocuteur,
# avec une expression précise (demandes de Stéphan du 24/11). FLUX 3 Klein local, file calcul-lourd. Usage : gen_s2_scenes_vues.sh [id…]
cd "$(dirname "$0")/../work/crossover" || exit 1
ST="hand-painted 2000s 2D point-and-click adventure game scene, painterly detailed backgrounds like classic adventure games, bold dark outlines, warm saturated colors, humorous storybook fantasy, characters with realistic adult proportions and ironic expressions, wide composition, no logo, no watermark, no frame, no text, no letters"
H="The hero is exactly the man from the reference picture: same face, same blond ponytail, same horned iron Viking helmet, same fur-collared studded leather armor, same round wooden shield strapped on his back, same pleated brown leather kilt with leather pouches, same fur-topped boots, same painted style; NOT a tartan kilt."
IN="a rugged adventurous archaeologist in his early forties with short brown hair and a few days of stubble, a battered brown fedora with a dark band, a worn dark brown leather jacket over a beige khaki shirt open at the collar with rolled sleeves, a canvas satchel strap across his chest, a coiled bullwhip at his hip"
DG="a tall anthropomorphic cartoon dog detective walking upright, short smooth brown fur, a long snout with a black nose, long floppy ears, a big cheerful toothy grin, a grey-blue suit with a white shirt and a wide tie with diagonal blue and black stripes, a matching grey-blue fedora hat, big bare brown dog feet without shoes"
RB="a small hyperactive cartoon rabbit-like creature with a smooth plain white body and no clothes, very long upright ears with pink insides, small round black dot eyes, a tiny pink nose, a huge wide grin full of small pointed teeth"
WZ="a very tall lanky old wizard, much taller than the hero, with a long grey beard, a tall pointed grey hat, long grey robes, a grey cloak and a gnarled wooden staff"
typeset -A P R
P[r_anneauxc]="$H Inside a colossal dark dwarven underground hall with giant stone pillars, on a narrow stone bridge over a fiery abyss. From left to right: first $WZ, standing behind the hero on the left, annoyed, arms crossed; second the hero, seen in strict side profile facing RIGHT toward the demon, his whole body turned to the right, leaning forward with his legs apart and his fists clenched back at his sides, shouting with all his might, mouth wide open, eyes narrowed with fury; a rippling cone-shaped blue shockwave of sound bursts straight out of his open mouth and travels horizontally to the right, widening as it goes, hitting a huge horned shadow demon of fire and smoke on the right end of the bridge, who is blown backwards. $ST"; R[r_anneauxc]=hero_s2/sel_profile_right.png
P[r_anneauxd]="$H Inside a colossal dark dwarven underground hall with giant stone pillars, on a narrow stone bridge over a fiery abyss. From left to right: first $WZ, standing behind the hero on the left, annoyed, gripping his tall wooden staff firmly in his right fist with its foot planted on the bridge, his left hand on his hip; second the hero, seen in strict side profile facing RIGHT toward the demon, his whole body turned to the right, leaning forward with his legs apart and his fists clenched back at his sides, shouting with all his might, mouth wide open, eyes narrowed with fury; a rippling cone-shaped blue shockwave of sound bursts straight out of his open mouth and travels horizontally to the right, widening as it goes, hitting a huge horned shadow demon of fire and smoke on the right end of the bridge, who is blown backwards. $ST"; R[r_anneauxd]=hero_s2/sel_profile_right.png
P[r_indianae]="$H He is seen in three-quarter view facing LEFT toward the archaeologist; his face shows nervous tension: eyes wide, teeth clenched in a worried grimace, a drop of sweat on his brow, no smile. Inside an ancient overgrown jungle temple lit by torches: a small golden idol on a carved stone pedestal in the middle, a pit full of snakes in the foreground, a huge round stone boulder at the top of a ramp behind. Two separate people, from left to right: first $IN, raising a warning hand toward the hero; second the hero on the right, carefully holding a big wheel of yellow cheese with both hands, ready to swap it with the idol. Each person wears only his own clothes. $ST"; R[r_indianae]=hero_s2/sel_34_left.png
P[r_sammaxg]="$H He is seen in three-quarter view facing LEFT toward the dog; his face is puzzled and doubtful: one eyebrow raised, mouth twisted sideways, no smile. A sunny desert roadside attraction along a dusty highway: a giant wheel of yellow cheese as big as a house on a wooden platform, a large blank weathered billboard, a vintage 1960s police sedan painted plain black and white with no lettering at all. Two separate figures, from left to right: first $DG, talking with a big grin; second the hero on the right, listening, with $RB perched on his shoulder. Each wears only his own clothes. There is no writing anywhere in the picture. $ST"; R[r_sammaxg]=hero_s2/sel_34_left.png
ids=("$@")
for id in $ids; do
  for s in 1 2; do
    out="${id}_$s.png"; [ -f "$out" ] && continue
    seed=$(( ${#id} * 1000 + s * 131 + 9191 ))
    flux-image "${P[$id]}" -i "${R[$id]}" -s 1280x720 --seed $seed -o "$out" >/dev/null 2>&1
    echo "$(date +%H:%M:%S) ok $out"
  done
done
